WITH base AS (SELECT *, LENGTH(level) AS level_length, COALESCE(level, 'OTHER') AS level_clean FROM employees WHERE hire_date > DATE '2023-05-16'), joined AS (SELECT s.id, s.full_name, s.dept_id, s.manager_id, s.salary, s.level, s.level_length, p.budget FROM base s JOIN departments p ON s.dept_id = p.id), base_employees AS (SELECT id, full_name, dept_id, manager_id, level, level_length, level_length - salary AS level_length_minus_salary, ROUND(salary * 1.07, 2) AS salary_adjusted, COALESCE(level, 'DIRECT') AS resolved_level FROM joined WHERE level IS NOT NULL AND level IS DISTINCT FROM 'L4'), metrics AS (SELECT *, AVG(level_length_minus_salary) OVER (PARTITION BY manager_id, level ORDER BY level_length_minus_salary, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_avg_level_length_minus_salary, MIN(level_length_minus_salary) OVER (PARTITION BY manager_id, level ORDER BY level_length_minus_salary, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_min_level_length_minus_salary, COUNT(level_length_minus_salary) OVER (PARTITION BY manager_id, level ORDER BY level_length_minus_salary, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_count_level_length_minus_salary FROM base_employees) SELECT id, dept_id, metric, reading FROM (SELECT id, dept_id, last4_min_level_length_minus_salary, salary_adjusted FROM metrics) src UNPIVOT (reading FOR metric IN (last4_min_level_length_minus_salary, salary_adjusted AS SALARY_ADJUSTED)) long_rows;
